starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "ami_id" {
  description = "Input variable ami_id."
  type        = string
}

variable "instance_type" {
  description = "Input variable instance_type."
  type        = string
  default     = "t2.micro"
}

variable "subnet_id" {
  description = "Input variable subnet_id."
  type        = string
}

variable "vpc_id" {
  description = "Input variable vpc_id."
  type        = string
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_security_group" "this" {
  name        = "app-sg"
  description = "Application security group"
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "this" {
  # TODO - Complete the graded block.
  # Complete this block using the challenge requirements.
}

resource "aws_eip" "this" {
  domain   = "vpc"
  instance = aws_instance.this.id
}

resource "aws_eip_association" "this" {
  instance_id = aws_instance.this.id
}

starter.outputs.tf:
output "instance_id" {
  value = aws_instance.this.id
}

output "public_ip" {
  value = aws_eip.this.public_ip
}
